7	/* ---------- xe cộ dùng chung: kiểu xe, màu, đặt từng phần của xe ---------- */
8	export type VehicleType = 'car' | 'bus' | 'bike';
9	export const TYPES: Record<VehicleType, { len: number; h: number; w: number; cl: number; ch: number; cw: number; co: number }> = {
