11	  bus: { len: 11, h: 2.6, w: 2.5, cl: 10.4, ch: 0.25, cw: 2.3, co: 0 },
12	  bike: { len: 1.9, h: 0.65, w: 0.6, cl: 0.55, ch: 1.0, cw: 0.45, co: -0.2 }
13	};
14	export const CAR_COLORS = [0xf2f2f0, 0xc9cdd1, 0x1d2126, 0xb3262a, 0x2b4f8f, 0x777d83, 0xe8e4d8];
15	export const BIKE_COLORS = [0xc0272d, 0x1f2a44, 0xe9e9e6, 0x2f7d4f, 0x2a2a2a];
