25	export interface LaneSpec { off: number; n: number; speed: number; bike?: number; bus?: number }
26	export interface BridgeVehicle { lane: number; dir: number; type: VehicleType; s: number; speed: number; color: number; hold?: number }
27	export interface Traffic {
28	  list: BridgeVehicle[]; x0: number; x1: number;
29	  body: THREE.InstancedMesh; cabin: THREE.InstancedMesh; head: THREE.InstancedMesh; tail: THREE.InstancedMesh;
30	}
31	/* lanes: [{ off (m từ tim cầu), n, speed, bike (tỉ lệ xe máy), bus (tỉ lệ xe buýt) }] — mỗi làn chạy cả hai chiều */
32	export function createTraffic(bridge: { life: THREE.Group }, { seed, x0, x1, lanes, busColor }: { seed: number; x0: number; x1: number; lanes: LaneSpec[]; busColor: number }): Traffic {
33	  const rnd = rng(seed), list: BridgeVehicle[] = [];
34	  for (const dir of [1, -1]) lanes.forEach(({ off, n, speed, bike = 0, bus = 0.08 }) => {
35	    for (let k = 0; k < n; k++) {
36	      const r = rnd(), type: VehicleType = r < bike ? 'bike' : r < bus ? 'bus' : 'car';
37	      list.push({ lane: off, dir, type, s: x0 + (k + rnd() * 0.6) * (x1 - x0) / n, speed: speed * (0.85 + rnd() * 0.3),
38	        color: type === 'bike' ? BIKE_COLORS[k % BIKE_COLORS.length] : type === 'bus' ? busColor : CAR_COLORS[Math.floor(rnd() * CAR_COLORS.length)] });
39	    }
40	  });
41	  const box = new THREE.BoxGeometry(1, 1, 1);
42	  const T: Traffic = {
43	    list, x0, x1,
44	    body: new THREE.InstancedMesh(box, MAT.vehicle, list.length),
45	    cabin: new THREE.InstancedMesh(box, MAT.glass, list.length),
46	    head: new THREE.InstancedMesh(box, MAT.headLamp, list.length),
47	    tail: new THREE.InstancedMesh(box, MAT.tailLamp, list.length)
48	  };
49	  const col = new THREE.Color();
50	  list.forEach((v, i) => T.body.setColorAt(i, col.setHex(v.color)));
51	  for (const mm of [T.body, T.cabin, T.head, T.tail]) { mm.frustumCulled = false; mm.instanceMatrix.setUsage(THREE.DynamicDrawUsage); bridge.life.add(mm); }
52	  T.body.castShadow = true;
53	  return T;
54	}
55	/* closable: có theo lệnh đóng cầu của thời tiết (bão) không; Hầm vượt sông Hàn truyền false (hầm vẫn lưu thông) */
56	const HIDDEN_M = new THREE.Matrix4().makeScale(0, 0, 0);
57	const _base = new THREE.Vector3();
58	/* Không cấp phát mỗi khung (D-018); đèn pha/hậu ẩn ban ngày nên không ghi ma trận đèn khi ẩn (vị trí xe vẫn cộng dồn) */
59	export function stepTraffic(T: Traffic, dt: number, profile: Profile, closable = true) {
60	  const range = T.x1 - T.x0, base = _base, lamps = shared.uNight.value > 0.3;
61	  T.head.visible = T.tail.visible = lamps;
62	  for (let i = 0; i < T.list.length; i++) {
63	    const v = T.list[i], ty = TYPES[v.type];
64	    v.s += v.dir * v.speed * dt; if (v.s > T.x1) v.s -= range; if (v.s < T.x0) v.s += range;
65	    if (closable && vanished(i, weatherFx.clear)) {   // đóng cầu (bão): dọn dần xe
66	      T.body.setMatrixAt(i, HIDDEN_M); T.cabin.setMatrixAt(i, HIDDEN_M); if (lamps) { T.head.setMatrixAt(i, HIDDEN_M); T.tail.setMatrixAt(i, HIDDEN_M); }
67	      continue;
68	    }
69	    const y = profile(v.s), slope = (profile(v.s + 1) - profile(v.s - 1)) / 2;
70	    _q.setFromEuler(_e.set(0, v.dir > 0 ? 0 : Math.PI, Math.atan(slope * v.dir), 'YZX'));
71	    base.set(v.s, y + 0.03, v.dir * v.lane);                 // tọa độ cục bộ của group cầu
72	    placePart(T.body, i, base, _q, 0, 0.3 + ty.h / 2, ty.len, ty.h, ty.w);
73	    placePart(T.cabin, i, base, _q, ty.co * ty.len, 0.3 + ty.h + ty.ch / 2, ty.cl, ty.ch, ty.cw);
74	    if (!lamps) continue;
75	    placePart(T.head, i, base, _q, ty.len / 2 + 0.04, 0.3 + ty.h * 0.6, 0.1, 0.22, ty.w * 0.8);
76	    placePart(T.tail, i, base, _q, -ty.len / 2 - 0.04, 0.3 + ty.h * 0.6, 0.1, 0.22, ty.w * 0.8);
77	  }
78	  T.body.instanceMatrix.needsUpdate = T.cabin.instanceMatrix.needsUpdate = true;
79	  if (lamps) T.head.instanceMatrix.needsUpdate = T.tail.instanceMatrix.needsUpdate = true;
80	}
