32	      vehicles.push({ path, lane, dir, type, s: path.min + (k + rand() * 0.5) * range / count, speed,
33	        color: type === 'bike' ? BIKE_COLORS[k % BIKE_COLORS.length] : type === 'bus' ? 0xe8b923 : CAR_COLORS[Math.floor(rand() * CAR_COLORS.length)] });
34	    }
35	  };
36	  const lanes = [4.875, 8.625, 12.375];
37	  for (const dir of [1, -1]) {
38	    addLane(PATHS.axis, lanes[0], dir, 26, 15, { bike: 0.05, bus: 0.08 });
39	    addLane(PATHS.axis, lanes[1], dir, 30, 12.5, { bike: 0.3, bus: 0.06 });
40	    addLane(PATHS.axis, lanes[2], dir, 44, 9.5, { bike: 0.85, bus: 0 });
