47	  vBody = new THREE.InstancedMesh(box, MAT.vehicle, n);
48	  vCabin = new THREE.InstancedMesh(box, MAT.glass, n);
49	  vHead = new THREE.InstancedMesh(box, MAT.headLamp, n);
50	  vTail = new THREE.InstancedMesh(box, MAT.tailLamp, n);
51	  const col = new THREE.Color();
52	  vehicles.forEach((v, i) => { col.setHex(v.color); vBody.setColorAt(i, col); });
